/**
 * Return a pi resource loader with no filesystem discovery.
 *
 * Pi's default loader reads executable extensions and prompt-affecting files
 * from `cwd`, which is the agent-writable workspace in Lobu. Lobu supplies its
 * skills and instructions through the gateway instead, so the worker must not
 * derive session behavior from workspace or host files.
 */
import {
	createExtensionRuntime,
	type ResourceLoader,
} from "@mariozechner/pi-coding-agent";

export function createLobuResourceLoader(): ResourceLoader {
	return {
		getExtensions: () => ({
			extensions: [],
			errors: [],
			runtime: createExtensionRuntime(),
		}),
		getSkills: () => ({ skills: [], diagnostics: [] }),
		getPrompts: () => ({ prompts: [], diagnostics: [] }),
		getThemes: () => ({ themes: [], diagnostics: [] }),
		getAgentsFiles: () => ({ agentsFiles: [] }),
		getSystemPrompt: () => undefined,
		getAppendSystemPrompt: () => [],
		extendResources: () => {},
		reload: async () => {},
	};
}

