test("a symlink cycle under .pi/skills does not stall session boot", async () => {
	// pi's skill scan recurses into subdirectories and follows symlinks: it
	// stats the link target and recurses when it is a directory. A cycle the
	// agent leaves behind would therefore hang or blow the stack on every
	// later boot of that conversation. The `no*` flags on
	// DefaultResourceLoader do NOT prevent this — they discard results after
	// the walk has already happened — so this asserts the walk itself never
	// starts.
	const skills = join(workspace, ".pi", "skills", "loop");
	mkdirSync(skills, { recursive: true });
	symlinkSync(join(workspace, ".pi", "skills"), join(skills, "back"), "dir");

	const session = await boot();
	session.dispose();

	// Reaching here at all is the assertion: an unbounded walk would not
	// return. Confirm the cycle is genuinely traversable, so the test would
	// actually catch a regression rather than pass on a broken fixture.
	expect(existsSync(join(skills, "back", "loop", "back"))).toBe(true);
});

