121	  builtinOverrides,
122	  ...options
123	}: BuildAgentSessionOptions): Promise<CreateAgentSessionResult> {
124	  // Pi's defaults persist under ~/.pi and discover resources/config from cwd.
125	  // Lobu supplies explicit production state; keep every fallback in memory so
126	  // a worker session never depends on host or agent-writable workspace files.
127	  const cwd = options.cwd ?? options.sessionManager?.getCwd() ?? process.cwd();
128	  const settingsManager = options.settingsManager ?? SettingsManager.inMemory();
129	  const sessionManager = options.sessionManager ?? SessionManager.inMemory(cwd);
130	  const authStorage =
131	    options.authStorage ??
132	    options.modelRegistry?.authStorage ??
133	    AuthStorage.inMemory();
134	  const modelRegistry =
135	    options.modelRegistry ?? ModelRegistry.inMemory(authStorage);
136	  const resourceLoader = createLobuResourceLoader();
137	
138	  const result = await createAgentSession({
139	    ...options,
140	    cwd,
141	    settingsManager,
142	    sessionManager,
143	    authStorage,
144	    modelRegistry,
145	    resourceLoader,
146	  });
147	  const { session } = result;
