/**
 * Reproducer: does the system prompt the worker assembles actually reach the model?
 *
 * Boots a real pi session via buildAgentSession, assigns a marker system prompt
 * exactly the way session-runner.ts does, then calls session.prompt() with the
 * provider fetch intercepted so we can read the outgoing request body.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { AuthStorage, ModelRegistry } from "@mariozechner/pi-coding-agent";
import { buildDynamicOpenAIModel } from "../../../../../Users/burakemre/Code/lobu/.claude/worktrees/worker-owns-system-prompt/packages/agent-worker/src/runtime/model-resolver";
import { buildAgentSession } from "../../../../../Users/burakemre/Code/lobu/.claude/worktrees/worker-owns-system-prompt/packages/agent-worker/src/runtime/session-runner";

const MARKER = "LOBU_MARKER_SYSTEM_PROMPT_OWNED_BY_WORKER";

const SSE = [
  `data: ${JSON.stringify({ id: "1", object: "chat.completion.chunk", created: 0, model: "test-model", choices: [{ index: 0, delta: { role: "assistant", content: "ok" }, finish_reason: null }] })}`,
  "",
  `data: ${JSON.stringify({ id: "1", object: "chat.completion.chunk", created: 0, model: "test-model", choices: [{ index: 0, delta: {}, finish_reason: "stop" }] })}`,
  "",
  "data: [DONE]",
  "",
  "",
].join("\n");

const captured: string[] = [];
const realFetch = globalThis.fetch;
globalThis.fetch = (async (input: any, init?: any) => {
  const url = typeof input === "string" ? input : (input?.url ?? String(input));
  if (url.includes("127.0.0.1")) {
    captured.push(String(init?.body ?? ""));
    return new Response(SSE, {
      status: 200,
      headers: { "content-type": "text/event-stream" },
    });
  }
  return realFetch(input, init);
}) as typeof fetch;

const tempDir = mkdtempSync(join(tmpdir(), "repro-"));
try {
  const authStorage = AuthStorage.inMemory();
  authStorage.setRuntimeApiKey("openai", "test-key");
  const modelRegistry = ModelRegistry.inMemory(authStorage);
  const model = buildDynamicOpenAIModel({
    rawProvider: "openai",
    registryProvider: "openai",
    modelId: "test-model",
    providerBaseUrl: "http://127.0.0.1:59999/v1",
  });

  const { session } = await buildAgentSession({
    cwd: tempDir,
    model: model as any,
    tools: [],
    customTools: [],
    authStorage,
    modelRegistry,
  });

  console.log("pi base prompt length:", session.systemPrompt.length);
  console.log(
    "pi base prompt opens with:",
    JSON.stringify(session.systemPrompt.slice(0, 90))
  );

  // Exactly what session-runner.ts does today.
  session.agent.state.systemPrompt = MARKER;
  console.log(
    "after assignment, session.systemPrompt starts with MARKER:",
    session.systemPrompt.startsWith(MARKER)
  );

  await session.prompt("hi");

  console.log("captured requests:", captured.length);
  const body = JSON.parse(captured[0] ?? "{}");
  const sys = body.messages?.find((m: any) => m.role === "system");
  const sysText =
    typeof sys?.content === "string"
      ? sys.content
      : JSON.stringify(sys?.content);
  console.log("=== WHAT THE MODEL RECEIVED ===");
  console.log("system message length:", sysText?.length);
  console.log("contains MARKER:", sysText?.includes(MARKER));
  console.log(
    "contains pi opener:",
    sysText?.includes("expert coding assistant operating inside pi")
  );
  console.log("contains pi docs block:", sysText?.includes("Pi documentation"));
  console.log("--- first 200 chars ---");
  console.log(sysText?.slice(0, 200));

  session.dispose();
} finally {
  rmSync(tempDir, { recursive: true, force: true });
}

