cat > probe2.ts <<'EOF'
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { buildAgentSession } from "./src/runtime/session-runner";
import { createLobuTools } from "./src/runtime/tools";

const tempDir = mkdtempSync(join(tmpdir(), "probe2-"));
try {
  const tools = createLobuTools(tempDir);
  const { session } = await buildAgentSession({
    cwd: tempDir,
    tools: tools.map((t) => t.name),
    builtinOverrides: tools,
    customTools: [],
  });
  console.log("=== FULL pi base prompt with real Lobu tools ===");
  console.log(session.systemPrompt);
  session.dispose();
} finally {
  rmSync(tempDir, { recursive: true, force: true });
}
EOF
bun run probe2.ts 2>&1 | tail -45

